  redo: string;
  source: string;
  sourceRequired: string;
  textStyle: (current: string) => string;
  text: string;
  paragraph: string;
  heading: (level: number) => string;
  headingShort: (level: number) => string;
  link: string;
  linkUrl: string;
  linkInvalid: string;
  applyLink: string;
  removeLink: string;
  image: string;
