  dragHandleHint: "Drag to reorder · Alt+↑/↓ to move",
  blockMoved: (direction) => `Block moved ${direction}.`,
  taskItem: "Task item",
};

export type MarkdownEditorContextValue = {
  editor: Editor | null;
  disabled: boolean;
  readOnly: boolean;
  /** Rich editing is possible: the editor is mounted, enabled, writable and not showing its Markdown source. */
  editable: boolean;
  labels: MarkdownEditorLabels;
  source: boolean;
  markdown: string;
  sourceRequired: boolean;
  isUrlAllowed: MarkdownUrlPolicy;
  setSource: (source: boolean) => void;
  setMarkdown: (value: string) => void;
  setContentAttributes: (attributes: Record<string, string>) => void;
  canUpload: boolean;
  uploads: MarkdownImageUpload[];
  upload: (files: File[], position?: number) => void;
  retryUpload: (id: string) => void;
  removeUpload: (id: string) => void;
  uploadError: string | null;
};

export const MarkdownEditorContext = createContext<MarkdownEditorContextValue | null>(null);

export function useMarkdownEditor() {
  const context = useContext(MarkdownEditorContext);
  if (!context) throw new Error("Markdown editor parts require a MarkdownEditor parent.");
  return context;
}

"use client";

import type { Editor } from "@tiptap/core";
import { closeHistory } from "@tiptap/pm/history";
import { NodeSelection } from "@tiptap/pm/state";
import { GripVerticalIcon } from "lucide-react";
import { type RefObject, useEffect, useRef, useState } from "react";
import { Button } from "@/components/control-ui/ui/button";
import { LiveStatus } from "@/components/control-ui/ui/live-status";
import { useMarkdownEditor } from "./context";
import { createDragPreview } from "./drag-preview";

type BlockHandle = { position: number; top: number };

/** The gutter sits outside every block, so the pointer's x is clamped into the text column before the hit test. */
function blockPositionAt(view: Editor["view"], event: MouseEvent): number | null {
  const rect = view.dom.getBoundingClientRect();
  const style = getComputedStyle(view.dom);
  const gutter = Number.parseFloat(style.paddingInlineStart);
  const left = style.direction === "rtl" ? Math.min(event.clientX, rect.right - gutter) : Math.max(event.clientX, rect.left + gutter);
  const hit = view.posAtCoords({ left, top: event.clientY });
  if (!hit) return null;
  const resolved = view.state.doc.resolve(hit.pos);
  return resolved.depth > 0 ? resolved.before(1) : hit.pos;
}

export function MarkdownEditorDragHandle({ container }: { container: RefObject<HTMLDivElement | null> }) {
  const { editor, editable, labels } = useMarkdownEditor();
  const [block, setBlock] = useState<BlockHandle | null>(null);
  const [announcement, setAnnouncement] = useState("");
  const button = useRef<HTMLButtonElement>(null);
  const dragging = useRef(false);
  const preview = useRef<HTMLDivElement | null>(null);
  const preparedDrag = useRef<ReturnType<typeof prepareDrag> | null>(null);

  useEffect(() => {
    const surface = container.current;
    if (!editor || editor.isDestroyed || !surface || !editable) return;
    const view = editor.view;
    let frame = 0;
    let latestEvent: MouseEvent | null = null;
    function show(blockPosition: number) {
      if (!editor || !surface) return;
      const node = editor.view.nodeDOM(blockPosition);
      if (!(node instanceof HTMLElement)) return;
      const top = node.getBoundingClientRect().top - surface.getBoundingClientRect().top + surface.scrollTop;
      setBlock((current) => (current?.position === blockPosition && current.top === top ? current : { position: blockPosition, top }));
    }
    function updateHandle(event: MouseEvent) {
      if (!editor || dragging.current || button.current?.contains(event.target instanceof Node ? event.target : null)) return;
      const blockPosition = blockPositionAt(editor.view, event);
      if (blockPosition !== null) show(blockPosition);
    }
    function track(event: MouseEvent) {
      latestEvent = event;
      if (frame) return;
      frame = requestAnimationFrame(() => {
        frame = 0;
        if (latestEvent) updateHandle(latestEvent);
      });
    }
    function selectionChanged() {
      if (!editor || dragging.current) return;
      const { $from } = editor.state.selection;
      show($from.depth > 0 ? $from.before(1) : $from.pos);
    }
    function hide() {
      cancelAnimationFrame(frame);
      frame = 0;
      latestEvent = null;
      if (!dragging.current && document.activeElement !== button.current) setBlock(null);
    }
    surface.addEventListener("mousemove", track);
    surface.addEventListener("mouseleave", hide);
    editor.on("transaction", selectionChanged).on("focus", selectionChanged);
    return () => {
      cancelAnimationFrame(frame);
      surface.removeEventListener("mousemove", track);
      surface.removeEventListener("mouseleave", hide);
      editor.off("transaction", selectionChanged).off("focus", selectionChanged);
      view.dragging = null;
      preview.current?.remove();
      preview.current = null;
      preparedDrag.current = null;
      dragging.current = false;
    };
  }, [editor, container, editable]);

  if (!editor || !editable) return null;
  const selected = editor.state.selection.$from;
  const position = block?.position ?? (selected.depth > 0 ? selected.before(1) : selected.pos);

  function prepareDrag() {
    if (!editor || editor.isDestroyed) return null;
    const selection = NodeSelection.create(editor.state.doc, position);
    const node = editor.view.nodeDOM(position);
    const { dom, text, slice } = editor.view.serializeForClipboard(selection.content());
    return {
      position,
      document: editor.state.doc,
      selection,
      html: dom.innerHTML,
      text,
      slice,
      preview: node instanceof HTMLElement ? createDragPreview(node) : null,
    };
  }

  function move(direction: -1 | 1) {
    if (!editor) return;
    const { doc, tr } = editor.state;
    const node = doc.nodeAt(position);
    if (!node) return;
    const adjacent = direction === -1 ? doc.resolve(position).nodeBefore : doc.nodeAt(position + node.nodeSize);
    if (!adjacent) return;
    const target = direction === -1 ? position - adjacent.nodeSize : position + adjacent.nodeSize;
    tr.delete(position, position + node.nodeSize).insert(target, node);
    tr.setSelection(NodeSelection.create(tr.doc, target));
    editor.view.dispatch(closeHistory(tr).scrollIntoView());
    setAnnouncement(labels.blockMoved(direction === -1 ? "up" : "down"));
  }

  return (
    <>
      <Button
        ref={button}
        type="button"
        variant="ghost"
        size="xs"
        iconOnly
        data-markdown-drag-handle=""
        data-visible={block ? "" : undefined}
        aria-label={labels.dragHandle}
        aria-description={labels.dragHandleDescription}
        title={labels.dragHandleHint}
        draggable
        style={{
          insetBlockStart: block?.top,
          "--cui-button-background": "transparent",
          "--cui-button-hover-background": "transparent",
          "--cui-button-press-background": "transparent",
          "--cui-button-shadow": "0 0 transparent",
          "--cui-button-hover-shadow": "0 0 transparent",
        }}
        onClick={() => editor.commands.setNodeSelection(position)}
        onPointerDown={() => {
          preparedDrag.current = prepareDrag();
        }}
        onPointerUp={() => {
          preparedDrag.current = null;
        }}
        onKeyDown={(event) => {
          if (!event.altKey || !["ArrowUp", "ArrowDown"].includes(event.key)) return;
          event.preventDefault();
          move(event.key === "ArrowUp" ? -1 : 1);
        }}
        onDragStart={(event) => {
          const prepared = preparedDrag.current;
          const payload = prepared?.position === position && prepared.document === editor.state.doc ? prepared : prepareDrag();
          preparedDrag.current = null;
          if (!payload) {
            event.preventDefault();
            return;
          }
          const { view } = editor;
          const { html, text, slice, selection, preview: ghost } = payload;
          dragging.current = true;
          view.dispatch(view.state.tr.setSelection(selection));
          event.dataTransfer.clearData();
          event.dataTransfer.setData("text/html", html);
          event.dataTransfer.setData("text/plain", text);
          event.dataTransfer.effectAllowed = "copyMove";
          if (ghost) {
            preview.current?.remove();
            container.current?.append(ghost);
            preview.current = ghost;
            event.dataTransfer.setDragImage(ghost, 0, 0);
          }
          view.dragging = { slice, move: true };
        }}
        onDragEnd={() => {
          editor.view.dragging = null;
          dragging.current = false;
          preview.current?.remove();
          preview.current = null;
          preparedDrag.current = null;
          setBlock(null);
        }}
      >
        <GripVerticalIcon aria-hidden="true" />
      </Button>
      <LiveStatus message={announcement} />
    </>
  );
}

export function createDragPreview(node: HTMLElement) {
  const preview = document.createElement("div");
  preview.className = "tiptap";
  preview.dataset.markdownDragPreview = "";
  preview.setAttribute("aria-hidden", "true");
  preview.style.inlineSize = `${Math.min(node.getBoundingClientRect().width, 320)}px`;
  let remainingNodes = 80;
  let remainingText = 2000;
  function clonePreview(source: Node): Node {
    remainingNodes--;
    const clone = source.cloneNode(false);
    if (clone instanceof HTMLElement) {
      clone.classList.remove("ProseMirror-selectednode");
      clone.removeAttribute("id");
    }
    if (clone instanceof Text) {
      clone.data = clone.data.slice(0, remainingText);
      remainingText -= clone.data.length;
    }
    for (const child of source.childNodes) {
      if (remainingNodes === 0 || remainingText === 0) break;
      clone.appendChild(clonePreview(child));
    }
    return clone;
  }
  preview.append(clonePreview(node));
  return preview;
}

import { Extension, type Extensions, type JSONContent, Node } from "@tiptap/core";
import Image from "@tiptap/extension-image";
import { TaskList } from "@tiptap/extension-list";
import Paragraph from "@tiptap/extension-paragraph";
import { TableKit } from "@tiptap/extension-table";
import { Markdown, MarkdownManager } from "@tiptap/markdown";
import StarterKit from "@tiptap/starter-kit";
import { markdownHeadingAttributes } from "@/components/control-ui/ui/markdown-heading";
import { MarkdownTaskItem } from "./task-item";

const MarkdownHeadings = Extension.create({
  name: "markdownHeadings",
  addGlobalAttributes() {
    return [
      {
        types: ["heading"],
        attributes: {
          markdownHeading: {
            default: null,
            renderHTML: (attributes) =>
              markdownHeadingAttributes(([1, 2, 3, 4, 5, 6] as const).find((level) => level === attributes.level) ?? 1),
          },
        },
      },
    ];
  },
});

export function isEditorUrl(value: string, image = false): boolean {
  if (!value || /[\s\\]/.test(value) || Array.from(value).some((character) => character.charCodeAt(0) < 32)) return false;
  if (value.startsWith("/") && !value.startsWith("//")) return true;
  if (!image && value.startsWith("#")) return true;
  try {
    const url = new URL(value);
    return ["https:", "http:", ...(image ? [] : ["mailto:"])].includes(url.protocol);
  } catch {
    return false;
  }
}

export type MarkdownUrlKind = "link" | "image";
/** Decides which URLs the editor keeps. Content with a refused URL stays in source mode, so nothing is dropped. */
export type MarkdownUrlPolicy = (url: string, kind: MarkdownUrlKind) => boolean;

/** Web apps only keep URLs that still resolve after a reload: HTTP(S), mailto, root-relative paths and anchors. */
export const persistentUrlPolicy: MarkdownUrlPolicy = (url, kind) => isEditorUrl(url, kind === "image");

export type MarkdownExtensionOptions = {
  /** Extra TipTap extensions, applied after the built-in Markdown set. */
  extensions?: Extensions;
  isUrlAllowed?: MarkdownUrlPolicy;
};

function safeImage(isUrlAllowed: MarkdownUrlPolicy) {
  return Image.extend({
    renderMarkdown: (node) => {
      const src = String(node.attrs?.src ?? "").replace(/[()]/g, (character) => `\\${character}`);
      const alt = String(node.attrs?.alt ?? "").replace(/[\\[\]]/g, (character) => `\\${character}`);
      const title = String(node.attrs?.title ?? "").replace(/[\\"]/g, (character) => `\\${character}`);
      return title ? `![${alt}](${src} "${title}")` : `![${alt}](${src})`;
    },
    // a pasted image with a refused URL would save as "![alt]()" and force the whole document into source mode
    parseHTML() {
      return [
        {
          tag: 'img[src]:not([src^="data:"])',
          getAttrs: (element) => (isUrlAllowed(element.getAttribute("src") ?? "", "image") ? null : false),
        },
      ];
    },
    addAttributes() {
      return {
        ...this.parent?.(),
        src: {
          default: null,
          parseHTML: (element) => {
            const src = element.getAttribute("src") ?? "";
            return isUrlAllowed(src, "image") ? src : null;
          },
          renderHTML: (attributes) => ({ src: isUrlAllowed(attributes.src ?? "", "image") ? attributes.src : undefined }),
        },
      };
    },
  });
}

const MarkdownParagraph = Paragraph.extend({
  parseMarkdown: (token, helpers) => {
    const content = helpers.parseInline(token.tokens ?? []);
    const first = content[0];
    const empty = content.length === 1 && first?.type === "text" && ["&nbsp;", "\u00a0"].includes(first.text ?? "");
    return helpers.createNode("paragraph", undefined, empty ? [] : content);
  },
});

export const ImageUpload = Node.create({
  name: "imageUpload",
  group: "block",
  atom: true,
  selectable: true,
  addAttributes: () => ({ id: { default: null }, name: { default: "Image" } }),
  renderHTML: ({ node }) => ["div", { "data-image-upload": "", role: "status" }, `Image: ${node.attrs.name}`],
  renderMarkdown: () => "",
});

export function markdownExtensions({ extensions = [], isUrlAllowed = persistentUrlPolicy }: MarkdownExtensionOptions = {}) {
  return [
    StarterKit.configure({
      underline: false,
      paragraph: false,
      link: { openOnClick: false, isAllowedUri: (url) => isUrlAllowed(url, "link") },
    }),
    MarkdownParagraph,
    MarkdownHeadings,
    safeImage(isUrlAllowed).configure({ allowBase64: false, inline: true }),
    TaskList,
    MarkdownTaskItem.configure({ nested: true, HTMLAttributes: { "data-type": "taskItem" } }),
    TableKit.configure({ table: { resizable: false } }),
    ImageUpload,
    Markdown,
    ...extensions,
  ];
}

export function createMarkdownCodec(options?: MarkdownExtensionOptions) {
  return new MarkdownManager({ extensions: markdownExtensions(options) });
}

const supportedTokens = new Set([
  "space",
  "code",
  "heading",
  "hr",
  "blockquote",
  "list",
  "list_item",
  "paragraph",
  "text",
  "escape",
  "link",
  "image",
  "strong",
  "em",
  "codespan",
  "br",
  "del",
  "table",
  "def",
  "taskList",
  "taskItem",
]);

function unsupportedToken(value: unknown, isUrlAllowed: MarkdownUrlPolicy): boolean {
  if (Array.isArray(value)) return value.some((item) => unsupportedToken(item, isUrlAllowed));
  if (typeof value !== "object" || value === null) return false;
  if ("type" in value && typeof value.type === "string") {
    if (!supportedTokens.has(value.type)) return true;
    if (
      (value.type === "image" || value.type === "link") &&
      "href" in value &&
      typeof value.href === "string" &&
      !isUrlAllowed(value.href, value.type)
    )
      return true;
  }
  return Object.values(value).some((item) => unsupportedToken(item, isUrlAllowed));
}

export function requiresMarkdownSource(
  markdown: string,
  codec: MarkdownManager,
  isUrlAllowed: MarkdownUrlPolicy = persistentUrlPolicy,
): boolean {
  return unsupportedToken(codec.instance.lexer(markdown), isUrlAllowed);
}

export function hasMarkdownContent(document: JSONContent): boolean {
  if (document.type === "image") return true;
  if (document.type === "text" && document.text?.trim()) return true;
  return document.content?.some(hasMarkdownContent) ?? false;
}

