export function MarkdownEditorLink() {
  const { editor, editable, labels, isUrlAllowed } = useMarkdownEditor();
  const linked = useEditorState({ editor, selector: ({ editor: current }) => Boolean(current?.isActive("link")) });
  const [open, setOpen] = useState(false);
  const [url, setUrl] = useState("");
  const [checked, setChecked] = useState(false);
  const href = url.trim();
  const valid = isUrlAllowed(href, "link");
  function apply() {
    if (!valid || !editable) return;
    editor?.chain().focus().extendMarkRange("link").setLink({ href }).run();
    setOpen(false);
  }
  return (
    <Popover
      open={open}
      onOpenChange={(next) => {
        setOpen(next);
        if (!next) return;
        setUrl(editor?.getAttributes("link").href ?? "");
        setChecked(false);
      }}
    >
      <Tooltip>
        <TooltipTrigger
          render={<ToolbarButton type="button" iconOnly aria-label={labels.link} disabled={!editable} render={<PopoverTrigger />} />}
        >
          <LinkIcon aria-hidden="true" />
        </TooltipTrigger>
        <TooltipContent>{labels.link}</TooltipContent>
      </Tooltip>
      <PopoverContent
        finalFocus={() => editor?.view.dom ?? true}
        className="grid gap-3"
        onKeyDown={(event) => {
          if (event.key === "Enter" && event.target instanceof HTMLInputElement && !event.nativeEvent.isComposing) {
            event.preventDefault();
            event.stopPropagation();
            setChecked(true);
            apply();
          }
        }}
      >
        <PopoverTitle>{labels.link}</PopoverTitle>
        <MarkdownEditorUrlField
          label={labels.linkUrl}
          error={labels.linkInvalid}
          invalid={checked && href !== "" && !valid}
          value={url}
          onChange={(event) => setUrl(event.target.value)}
          onBlur={() => setChecked(true)}
          placeholder="https://example.com"
        />
        <div className="flex gap-2">
          <Button type="button" disabled={!valid || !editable} onClick={apply}>
            {labels.applyLink}
          </Button>
          <Button
            type="button"
            variant="ghost"
            disabled={!editable || !linked}
            onClick={() => {
              editor?.chain().focus().extendMarkRange("link").unsetLink().run();
              setOpen(false);
            }}
          >
            {labels.removeLink}
          </Button>
        </div>
      </PopoverContent>
    </Popover>
  );
}

export function MarkdownEditorImage() {
  const { editor, editable, labels, canUpload, upload, isUrlAllowed } = useMarkdownEditor();
  const [open, setOpen] = useState(false);
  const [url, setUrl] = useState("");
  const [alt, setAlt] = useState("");
  const [checked, setChecked] = useState(false);
  const altId = useId();
  const fileInput = useRef<HTMLInputElement>(null);
  const src = url.trim();
  const valid = isUrlAllowed(src, "image");
  function insert() {
    if (!valid || !editable) return;
    editor?.chain().focus().setImage({ src, alt }).run();
    setOpen(false);
    setUrl("");
    setAlt("");
    setChecked(false);
  }
  return (
    <Popover open={open} onOpenChange={setOpen}>
      <Tooltip>
        <TooltipTrigger
          render={<ToolbarButton type="button" iconOnly aria-label={labels.image} disabled={!editable} render={<PopoverTrigger />} />}
        >
          <ImageIcon aria-hidden="true" />
        </TooltipTrigger>
        <TooltipContent>{labels.image}</TooltipContent>
      </Tooltip>
      <PopoverContent
        finalFocus={() => editor?.view.dom ?? true}
        className="grid gap-3"
        onKeyDown={(event) => {
          if (event.key === "Enter" && event.target instanceof HTMLInputElement && !event.nativeEvent.isComposing) {
            event.preventDefault();
            event.stopPropagation();
            setChecked(true);
            insert();
          }
        }}
      >
        <PopoverTitle>{labels.image}</PopoverTitle>
        <MarkdownEditorUrlField
          label={labels.imageUrl}
          error={labels.imageInvalid}
          invalid={checked && src !== "" && !valid}
          value={url}
          onChange={(event) => setUrl(event.target.value)}
          onBlur={() => setChecked(true)}
          placeholder="https://example.com/image.png"
        />
        <Label htmlFor={altId}>{labels.imageDescription}</Label>
        <Input id={altId} value={alt} onChange={(event) => setAlt(event.target.value)} />
        <Button type="button" disabled={!valid || !editable} onClick={insert}>
          {labels.image}
        </Button>
        {canUpload ? (
          <>
            <input
              ref={fileInput}
              type="file"
              accept={markdownImageTypes.join(",")}
              multiple
              hidden
              onChange={(event) => {
                upload(Array.from(event.target.files ?? []));
                event.target.value = "";
                setOpen(false);
              }}
            />
            <Button type="button" variant="ghost" disabled={!editable} onClick={() => fileInput.current?.click()}>
              {labels.uploadImages}
            </Button>
          </>
        ) : null}
      </PopoverContent>
    </Popover>
  );
}

export function MarkdownEditorUploads() {
  const { uploads, uploadError, retryUpload, removeUpload, disabled, labels } = useMarkdownEditor();
  return (
    <>
      {uploadError ? (
        <Text as="p" role="alert">
          {uploadError}
        </Text>
      ) : null}
      {uploads.length > 0 ? (
        <div data-control-ui="markdown-editor" data-control-family="markdown-editor" data-slot="uploads">
          <ChatComposerAttachments label={labels.uploads}>
            {uploads.map((item) => (
              <ChatComposerAttachment
                key={item.id}
                file={item.file}
                status={item.status}
                progress={item.progress}
                onRemove={disabled ? undefined : () => removeUpload(item.id)}
                removeLabel={labels.removeUpload(item.file.name)}
              />
            ))}
          </ChatComposerAttachments>
          {uploads
            .filter((item) => item.status === "error")
            .map((item) => (
              <div key={item.id} role="alert" className="flex items-center gap-2">
                <span>
                  {item.file.name}: {item.error}
                </span>
                <Button type="button" size="xs" disabled={disabled} onClick={() => retryUpload(item.id)}>
                  {labels.retryUpload}
                </Button>
              </div>
            ))}
        </div>
      ) : null}
    </>
  );
}

import type { Editor } from "@tiptap/core";
import type { Node as ProseMirrorNode } from "@tiptap/pm/model";
import { type MarkdownUrlPolicy, persistentUrlPolicy } from "./extensions";

export type MarkdownImage = { url: string; alt?: string; title?: string };
export type MarkdownImageUploader = (
  file: File,
  options: { signal: AbortSignal; onProgress: (progress: number) => void },
) => Promise<MarkdownImage>;
export type MarkdownImageUpload = {
  id: string;
  file: File;
  status: "uploading" | "error";
  progress?: number;
  error?: string;
};

export function findImageUpload(document: ProseMirrorNode, id: string) {
  let position: number | undefined;
  document.descendants((node, pos) => {
    if (node.type.name === "imageUpload" && node.attrs.id === id) position = pos;
  });
  return position;
}

export function completeImageUpload(
  editor: Editor,
  id: string,
  image: MarkdownImage,
  fallbackAlt: string,
  isUrlAllowed: MarkdownUrlPolicy = persistentUrlPolicy,
) {
  if (!isUrlAllowed(image.url, "image")) {
    throw new Error(
      isUrlAllowed === persistentUrlPolicy
        ? "The upload must return a permanent HTTP(S) or root-relative image URL."
        : "The upload returned an image URL this editor does not accept.",
    );
  }
  const position = findImageUpload(editor.state.doc, id);
  if (position === undefined) return;
  const imageType = editor.schema.nodes.image;
  const paragraphType = editor.schema.nodes.paragraph;
  if (!imageType || !paragraphType) throw new Error("Image uploads require image and paragraph nodes.");
  const node = imageType.create({ src: image.url, alt: image.alt ?? fallbackAlt, title: image.title ?? null });
  editor.view.dispatch(
    editor.state.tr.replaceWith(position, position + 1, paragraphType.create(null, node)).setMeta("addToHistory", false),
  );
}

export const markdownImageTypes = ["image/png", "image/jpeg", "image/gif", "image/webp", "image/avif"];

import type { Editor } from "@tiptap/core";
import { useEffect, useId, useRef, useState } from "react";
import { defaultMarkdownEditorLabels, type MarkdownEditorLabels } from "./context";
import { type MarkdownUrlPolicy, persistentUrlPolicy } from "./extensions";
import { completeImageUpload, findImageUpload, type MarkdownImageUpload, type MarkdownImageUploader, markdownImageTypes } from "./uploads";

export function useImageUploads(
  editor: Editor | null,
  uploader: MarkdownImageUploader | undefined,
  maxImageBytes: number,
  isUrlAllowed: MarkdownUrlPolicy = persistentUrlPolicy,
  labels: Pick<MarkdownEditorLabels, "uploadFailed" | "uploadRejected"> = defaultMarkdownEditorLabels,
) {
  const [uploads, setUploads] = useState<MarkdownImageUpload[]>([]);
  const [uploadError, setUploadError] = useState<string | null>(null);
  const uploadPrefix = useId();
  const nextId = useRef(0);
  const jobs = useRef(new Map<string, { file: File; controller: AbortController }>());

  function discard(id: string) {
    jobs.current.get(id)?.controller.abort();
    jobs.current.delete(id);
    setUploads((current) => current.filter((item) => item.id !== id));
  }

  function cancelAll() {
    for (const job of jobs.current.values()) job.controller.abort();
    jobs.current.clear();
    setUploads([]);
  }

  useEffect(() => {
    const activeJobs = jobs.current;
    return () => {
      for (const job of activeJobs.values()) job.controller.abort();
      activeJobs.clear();
    };
  }, []);

  useEffect(() => {
    if (!editor) return;
    const prune = () => {
      for (const id of jobs.current.keys()) {
        if (findImageUpload(editor.state.doc, id) === undefined) {
          jobs.current.get(id)?.controller.abort();
          jobs.current.delete(id);
          setUploads((current) => current.filter((item) => item.id !== id));
        }
      }
    };
    editor.on("update", prune);
    return () => {
      editor.off("update", prune);
    };
  }, [editor]);

  async function run(id: string, file: File) {
    if (!editor || !uploader) return;
    const controller = new AbortController();
    jobs.current.set(id, { file, controller });
    setUploads((current) => [...current.filter((item) => item.id !== id), { id, file, status: "uploading" }]);
    try {
      const image = await uploader(file, {
        signal: controller.signal,
        onProgress: (progress) => {
          if (controller.signal.aborted || !Number.isFinite(progress)) return;
          setUploads((current) =>
            current.map((item) => (item.id === id ? { ...item, progress: Math.max(0, Math.min(100, progress)) } : item)),
          );
        },
      });
      if (controller.signal.aborted || editor.isDestroyed) return;
      completeImageUpload(editor, id, image, file.name, isUrlAllowed);
      discard(id);
    } catch (error) {
      if (controller.signal.aborted) return;
      setUploads((current) =>
        current.map((item) =>
          item.id === id
            ? {
                ...item,
                status: "error",
                error: error instanceof Error ? error.message : labels.uploadFailed,
              }
            : item,
        ),
      );
    }
  }

  function upload(files: File[], position?: number) {
    if (!editor || !uploader || !editor.isEditable) return;
    setUploadError(null);
    let insertAt = position ?? editor.state.selection.to;
    for (const file of files) {
      if (!markdownImageTypes.includes(file.type) || file.size > maxImageBytes) {
        setUploadError(labels.uploadRejected(Math.round(maxImageBytes / 1024 / 1024)));
        continue;
      }
      const id = `${uploadPrefix}-${nextId.current++}`;
      editor
        .chain()
        .focus()
        .insertContentAt(insertAt, { type: "imageUpload", attrs: { id, name: file.name } })
        .run();
      insertAt = editor.state.selection.to;
      void run(id, file);
    }
  }

  function removeUpload(id: string) {
    discard(id);
    if (!editor) return;
    const position = findImageUpload(editor.state.doc, id);
    if (position !== undefined) editor.view.dispatch(editor.state.tr.delete(position, position + 1).setMeta("addToHistory", false));
  }

  function retryUpload(id: string) {
    const job = jobs.current.get(id);
    if (job) {
      job.controller.abort();
      void run(id, job.file);
    }
  }

  return { uploads, uploadError, upload, retryUpload, removeUpload, cancelAll };
}

